public class BadHostnameVerifierDetector extends Detector implements SourceCodeScanner {
    private static final String HOSTNAME_VERIFIER = "javax.net.ssl.HostnameVerifier";
    private static final String VERIFY_METHOD = "verify";

    @Override
    public List<Class<? extends UElement>> getApplicableUElementTypes() {
        return Collections.singletonList(UMethod.class);
    }

    @Override
    public UElementHandler createUElementHandler(final JavaContext context) {
        return new UElementHandler() {
            @Override
            public void visitMethod(@NonNull UMethod node) {
                if (!VERIFY_METHOD.equals(node.getName())) return;
                PsiClass containingClass = node.getContainingClass();
                if (containingClass == null) return;
                if (!context.getEvaluator().implementsInterface(containingClass, HOSTNAME_VERIFIER, false)) return;
                // check method signature: String hostname, SSLSession session returns boolean
                if (node.getReturnType() == null || !context.getEvaluator().getTypeClass(node.getReturnType()).getQualifiedName().equals("boolean")) return;
                UExpression body = node.getUastBody();
                if (body instanceof UBlockExpression) {
                    List<UExpression> expressions = ((UBlockExpression) body).getExpressions();
                    if (expressions.size() == 1 && expressions.get(0) instanceof UReturnExpression) {
                        UReturnExpression ret = (UReturnExpression) expressions.get(0);
                        UExpression returnExpr = ret.getReturnExpression();
                        if (returnExpr != null && Boolean.TRUE.equals(returnExpr.evaluate())) {
                            context.report(ISSUE, node, context.getLocation(node), "Returning `true` in `verify` causes insecure hostname verification");
                        }
                    }
                }
            }
        };
    }

    static final Issue ISSUE = Issue.create(
        "BadHostnameVerifier",
        "Insecure HostnameVerifier",
        "This check looks for implementations of `HostnameVerifier` whose `verify` method always returns true...",
        Category.SECURITY,
        6,
        Severity.WARNING,
        new Implementation(BadHostnameVerifierDetector.class, Scope.JAVA_FILE_SCOPE)
    );
}

